      out.write("<script>\n");
      out.write("(function(){\n");
      out.write("  const thumbs = Array.from(document.querySelectorAll('.rv-thumb'));\n");
      out.write("  const mainImg = document.getElementById('rvMainImg');\n");
      out.write("  const countEl = document.getElementById('rvPhotoCount');\n");
      out.write("  const prevBtn = document.querySelector('.rv-prev');\n");
      out.write("  const nextBtn = document.querySelector('.rv-next');\n");
      out.write("\n");
      out.write("  if(!mainImg || thumbs.length === 0) return;\n");
      out.write("\n");
      out.write("  let cur = 0;\n");
      out.write("  const total = thumbs.length;\n");
      out.write("\n");
      out.write("  function setActive(idx){\n");
      out.write("    cur = (idx + total) % total;\n");
      out.write("    const src = thumbs[cur].dataset.src;\n");
      out.write("    mainImg.src = src;\n");
      out.write("\n");
      out.write("    thumbs.forEach(t => t.classList.remove('is-active'));\n");
      out.write("    thumbs[cur].classList.add('is-active');\n");
      out.write("\n");
      out.write("    if(countEl) countEl.textContent = (cur + 1) + \" / \" + total;\n");
      out.write("    thumbs[cur].scrollIntoView({block:'nearest', inline:'nearest', behavior:'smooth'});\n");
      out.write("  }\n");
      out.write("\n");
      out.write("  thumbs.forEach(t => {\n");
      out.write("    t.addEventListener('click', () => setActive(parseInt(t.dataset.idx, 10)));\n");
      out.write("  });\n");
      out.write("  if(prevBtn) prevBtn.addEventListener('click', () => setActive(cur - 1));\n");
      out.write("  if(nextBtn) nextBtn.addEventListener('click', () => setActive(cur + 1));\n");
      out.write("})();\n");
      out.write("</script>\n");
